#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<long long> a(N), b(N);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;

    long long answer = 0;
    vector<long long> gains;
    gains.reserve(N);

    for (int i = 0; i < N; ++i) {
        answer += max(0LL, a[i] - b[i]);
        gains.push_back(min(a[i], b[i]));
    }

    sort(gains.rbegin(), gains.rend());

    int take = min(N, K + 1);
    for (int i = 0; i < take; ++i) {
        answer += gains[i];
    }

    cout << answer << '\n';
    return 0;
}
